def compute(vars):
    purchase_price_millions = vars["v1"]
    sites_purchased = vars["v2"]

    if sites_purchased == 0:
        return None

    price_per_site_millions = purchase_price_millions / sites_purchased
    price_per_site_thousands = price_per_site_millions * 1000

    return {
        "value": price_per_site_thousands,
        "trace": {
            "purchase_price_millions": purchase_price_millions,
            "sites_purchased": sites_purchased,
            "price_per_site_millions": price_per_site_millions,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "per site"
            }
        }
    }
